package com.skyreserve.repository; import com.skyreserve.model.Flight; import java.util.List; import java.util.Optional; import org.springframework.data.jpa.repository.JpaRepository; public interface FlightRepository extends JpaRepository<Flight,Long>{List<Flight> findBySourceIgnoreCaseAndDestinationIgnoreCaseAndActiveTrue(String source,String destination); Optional<Flight> findByFlightNumberIgnoreCase(String flightNumber); List<Flight> findByActiveTrue();}